/* ================= ruta (autobús) ================= */
function routeInit(R){ const pts=R.map(p=>[p[0],p[1]]); const cum=[0]; for(let i=1;i<pts.length;i++) cum.push(cum[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1])); return {pts,cum,len:cum[cum.length-1]}; }
function rAt(s){ const R=G.route; s=Math.max(0,Math.min(R.len,s)); let i=1; while(i<R.cum.length-1&&R.cum[i]<s) i++; const a=R.pts[i-1], b=R.pts[i]; const l=R.cum[i]-R.cum[i-1]||1; const f=(s-R.cum[i-1])/l; return [a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f,Math.atan2(b[1]-a[1],b[0]-a[0])]; }
function rOff(s,off){ const p=rAt(s); return [p[0]-Math.sin(p[2])*off,p[1]+Math.cos(p[2])*off,p[2]]; }
/* puntos fijos (sin azar) alrededor de un centro, para dibujar público */
function blob(cx,cy,n,rx,ry,seed){ const o=[]; let a=(seed|0)*2654435761>>>0; const r=()=>{ a=(a*1103515245+12345)>>>0; return (a>>>8)/16777216; }; for(let i=0;i<n;i++){ const t=r()*Math.PI*2, d=Math.sqrt(r()); o.push([cx+Math.cos(t)*d*rx,cy+Math.sin(t)*d*ry]); } return o; }
function inPlaza(x,y){ const p=PLAZA_MAYOR; let ins=false; for(let i=0,j=p.length-2;i<p.length;j=i,i+=2){ if(((p[i+1]>y)!==(p[j+1]>y))&&(x<(p[j]-p[i])*(y-p[i+1])/(p[j+1]-p[i+1])+p[i])) ins=!ins; } return ins; }
function lg(es,en,c){ G.log.unshift({t:G.clock(),txt:L(es,en),c:c||''}); if(G.log.length>40) G.log.length=40; }
function hhmm(min){ min=Math.round(min*60)/60; const h=Math.floor(min/60), m=Math.floor(min%60), s=Math.round((min*60)%60); return h+':'+String(m).padStart(2,'0'); }

/* ================= mapa ================= */
function layer(key){ if(LAYERS[key]) return LAYERS[key]; const M=C.MAPS[key], k=2; const c=document.createElement('canvas'); c.width=M.w*k; c.height=M.h*k; const g=c.getContext('2d'); g.scale(k,k);
  g.fillStyle='#5d6166'; g.fillRect(0,0,M.w,M.h);
  const poly=(p,dx,dy)=>{ g.beginPath(); for(let i=0;i<p.length;i+=2){ if(i) g.lineTo(p[i]+(dx||0),p[i+1]+(dy||0)); else g.moveTo(p[i]+(dx||0),p[i+1]+(dy||0)); } g.closePath(); };
  g.fillStyle='#77736a'; (M.q||[]).forEach(p=>{ poly(p); g.fill(); });
  if(M.g){ g.fillStyle='#5f7a5c'; M.g.forEach(p=>{ poly(p); g.fill(); }); }
  if(M.r){ g.lineCap='round'; g.lineJoin='round'; g.strokeStyle='#4f5358'; g.lineWidth=8.6; g.beginPath(); M.r.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1])); g.stroke();
    g.strokeStyle='rgba(255,255,255,.55)'; g.lineWidth=0.25; g.setLineDash([3,4]); g.beginPath(); M.r.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1])); g.stroke(); g.setLineDash([]); }
  g.lineJoin='round'; g.strokeStyle='#80817f'; g.lineWidth=3.6; M.b.forEach(b=>{ poly(b); g.stroke(); }); g.strokeStyle='rgba(255,255,255,.10)'; g.lineWidth=4.4; M.b.forEach(b=>{ poly(b); g.stroke(); }); g.lineJoin='miter';
  g.fillStyle='rgba(8,10,14,.42)'; M.b.forEach(b=>{ poly(b,2.4,3); g.fill(); }); g.fillStyle='rgba(8,10,14,.22)'; M.b.forEach(b=>{ poly(b,4.8,6); g.fill(); });
  g.strokeStyle='#41464d'; g.lineWidth=0.5; M.b.forEach(b=>{ const hv=((Math.round(b[0]*7.3+b[1]*3.1)%9)+9)%9; const m=1+(hv-4)*0.05; g.fillStyle='rgb('+[43,47,53].map(v=>Math.round(v*m)).join(',')+')'; poly(b); g.fill(); g.save(); g.clip(); g.strokeStyle='rgba(255,255,255,.12)'; g.lineWidth=1.3; poly(b,0.7,0.8); g.stroke(); g.restore(); poly(b); g.stroke(); });
  if(M.x){ g.save(); g.strokeStyle='#8a8478'; g.lineWidth=3.4; g.lineCap='round'; M.x.forEach(p=>{ g.beginPath(); for(let i=0;i<p.length;i+=2){ if(i) g.lineTo(p[i],p[i+1]); else g.moveTo(p[i],p[i+1]); } g.stroke(); }); g.restore(); }
  if(M.st){ g.strokeStyle='#d6b25e'; g.lineWidth=1.6; poly(M.st); g.stroke(); g.fillStyle='rgba(214,178,94,.16)'; g.fill(); }
  const rg=g.createRadialGradient(M.w/2,M.h/2,Math.min(M.w,M.h)*0.35,M.w/2,M.h/2,Math.max(M.w,M.h)*0.72); rg.addColorStop(0,'rgba(0,0,0,0)'); rg.addColorStop(1,'rgba(0,0,0,.24)'); g.fillStyle=rg; g.fillRect(0,0,M.w,M.h);
  g.fillStyle='rgba(255,255,255,.62)'; g.font='600 6px system-ui,sans-serif'; g.textAlign='center'; g.textBaseline='middle'; (M.l||[]).forEach(l=>{ g.save(); g.translate(l[1],l[2]); g.rotate(l[3]||0); g.fillText(l[0],0,0); g.restore(); });
  LAYERS[key]=c; return c; }
function fit(){ if(!CV) return; const wrap=CV.parentNode; const cw=Math.max(200,wrap.clientWidth); const ch=Math.round(Math.min(cw*(G.mi==='bus'?1.1:0.85),Math.max(280,Math.min(window.innerHeight*0.45,520)))); const dpr=Math.min(2,window.devicePixelRatio||1);
  CV.width=Math.round(cw*dpr); CV.height=Math.round(ch*dpr); CV.style.width=cw+'px'; CV.style.height=ch+'px'; G.cv={cw,ch,dpr}; }
/* cámara: caja del mundo [x,y,w,h] que se ve entera */
function camBox(){ if(G.mi==='vis') return [330,150,280,270];
  const R=G.route; if(G.phase==='plan'||G.phase==='end'){ return [300,250,345,600]; }
  const p=rAt(G.bs); const w=150,h=170; const x=Math.max(0,Math.min(G.M.w-w,p[0]-w/2)), y=Math.max(0,Math.min(G.M.h-h,p[1]-h/2)); return [x,y,w,h]; }
function draw(){ if(!CTX||!G||!G.cv) return; const g=CTX, v=G.cv; const B=G.cam||(G.cam=camBox()); const s=Math.min(v.cw/B[2],v.ch/B[3]); const ox=(v.cw-B[2]*s)/2-B[0]*s, oy=(v.ch-B[3]*s)/2-B[1]*s;
  g.setTransform(1,0,0,1,0,0); g.fillStyle='#3c4046'; g.fillRect(0,0,CV.width,CV.height);
  g.setTransform(v.dpr*s,0,0,v.dpr*s,v.dpr*ox,v.dpr*oy); g.drawImage(layer(G.mapKey),0,0,G.M.w,G.M.h);
  const px=1/s; if(G.mi==='vis') drawVis(g,px); else drawBusM(g,px); }
function dot(g,x,y,r,c){ g.fillStyle=c; g.beginPath(); g.arc(x,y,r,0,Math.PI*2); g.fill(); }
function label(g,x,y,t,px,c,sz,bg){ g.font='700 '+(sz||11)*px+'px system-ui,sans-serif'; g.textAlign='center'; g.textBaseline='middle'; if(bg){ const w=g.measureText(t).width+8*px; g.fillStyle=bg; g.fillRect(x-w/2,y-8*px,w,16*px); } g.fillStyle=c||'#fff'; g.fillText(t,x,y); }
function arrow(g,x0,y0,x1,y1,px,c){ g.strokeStyle=c; g.lineWidth=7*px; g.lineCap='round'; g.beginPath(); g.moveTo(x0,y0); g.lineTo(x1,y1); g.stroke(); const a=Math.atan2(y1-y0,x1-x0); g.fillStyle=c; g.beginPath(); g.moveTo(x1+Math.cos(a)*12*px,y1+Math.sin(a)*12*px); g.lineTo(x1+Math.cos(a+2.3)*13*px,y1+Math.sin(a+2.3)*13*px); g.lineTo(x1+Math.cos(a-2.3)*13*px,y1+Math.sin(a-2.3)*13*px); g.closePath(); g.fill(); }
function pulse(g,x,y,px){ const t=(performance.now()/900)%1; g.strokeStyle='rgba(255,138,115,'+(1-t)+')'; g.lineWidth=3*px; g.beginPath(); g.arc(x,y,(8+22*t)*px,0,Math.PI*2); g.stroke(); dot(g,x,y,5*px,'#ff8a73'); }
function animOn(){ if(!RAF){ G.lastTs=0; RAF=requestAnimationFrame(loop); } }
function loop(ts){ RAF=0; if(!G||!/^#\/antidisturbios/.test(location.hash)||!document.getElementById('mi-cv')) return; const dt=G.lastTs?Math.min(0.1,(ts-G.lastTs)/1000):0; G.lastTs=ts;
  let more=false; if(G.mi==='bus') more=busTick(dt); else more=visTick(dt);
  if(G.mi==='bus'&&G.phase!=='plan'&&G.phase!=='end'){ const t=camBox(); const c=G.cam||t; const f=Math.min(1,dt*3); G.cam=c.map((v,i)=>v+(t[i]-v)*f); }
  draw(); if(more||G.pulse) RAF=requestAnimationFrame(loop); }

