const VBUD=300; /* segundos de juego hasta el cierre de los accesos (11:30 → 11:55, 1 s de juego = 5 s) */
function newVis(seed){ const M=C.MAPS.mayor; const fl=seed%2?'sol':'tol';
  /* el orden de la cola cambia con la partida; la persona 9 (la que se va) nunca es la primera */
  const ord=PEOPLE.map((_,i)=>i); let a=seed>>>0; const r=()=>{ a=(a*1103515245+12345)>>>0; return (a>>>8)/16777216; }; for(let i=ord.length-1;i>0;i--){ const j=Math.floor(r()*(i+1)); const t=ord[i]; ord[i]=ord[j]; ord[j]=t; } if(ord[0]===8){ ord[0]=ord[1]; ord[1]=8; }
  G={mi:'vis',seed,M,mapKey:'mayor',fl,F:FLOW[fl],phase:'plan',apr:G&&G.apr||false,E:ENT_MAYOR.map(()=> 'x'),log:[],dec:[],t:0,ord,pi:0,cur:null,done:0,inside:0,pressHit:false,out:0,res:null,ev:0,fb:null,vip:null,pulse:null};
  G.clock=()=>{ if(G.phase==='plan') return '11:20'; if(G.phase==='chk') return clk(690+G.t*5/60); return G.tclock||'11:57'; };
  G.dais=[447,305]; return G; }
function clk(min){ const h=Math.floor(min/60), m=Math.floor(min%60); return h+':'+String(m).padStart(2,'0'); }
function setE(i){ const cur=G.E[i]; const nxt=cur==='x'?'c':cur==='c'?(VEH.indexOf(i)>=0?'a':'x'):'x'; if(nxt==='a') G.E=G.E.map(v=>v==='a'?'x':v); G.E[i]=nxt; G.fb=null; }
function planCheck(){ const nC=G.E.filter(v=>v==='c').length, nA=G.E.filter(v=>v==='a').length; return {nC,nA,ok:nC===3&&nA===1}; }
function planScore(){ const F=G.F; let pc=0; const notes=[]; G.E.forEach((v,i)=>{ if(v!=='c') return; const rk=F.rank.indexOf(i); if(F.best.indexOf(i)>=0) pc+=4; else if(rk<5) pc+=2; });
  const ai=G.E.indexOf('a'); const near=G.E.map((v,i)=>v==='c'&&Math.hypot(ENT_MAYOR[i].x-ENT_MAYOR[ai].x,ENT_MAYOR[i].y-ENT_MAYOR[ai].y)<70?i:-1).filter(i=>i>=0);
  const pa=near.length?6:13; const wrong=G.E.filter((v,i)=>v==='c'&&F.best.indexOf(i)<0).length; return {pc,pa,near,wrong,tot:pc+pa}; }
function entName(i){ return L('Acceso ','Entrance ')+(i+1)+' ('+L(ENT_MAYOR[i].c,ENT_MAYOR[i].c.replace('SO','SW').replace('NO','NW').replace(/^O$/,'W'))+')'; }
function startChk(){ const ps=planScore(); G.ps=ps; G.bud=VBUD-25*ps.wrong; const cs=G.E.map((v,i)=>v==='c'?i:-1).filter(i=>i>=0).sort((x,y)=>G.F.rank.indexOf(x)-G.F.rank.indexOf(y)); G.mine=cs[0];
  const ai=G.E.indexOf('a');
  G.dec.push({ph:1,ok:ps.pc===12?2:ps.pc>=6?1:0,t:L('Controles de acceso','Public checkpoints'),r:G.E.map((v,i)=>v==='c'?(i+1):null).filter(x=>x).join(', '),why:ps.wrong?L('Pusiste '+ps.wrong+' control(es) lejos de por donde llega la gente: más vueltas y más cola en tu control (−'+(25*ps.wrong)+' s de margen). Lo ideal: '+G.F.best.map(i=>i+1).join(', ')+'.','You put '+ps.wrong+' checkpoint(s) away from where people arrive: longer detours and more queue at yours (−'+(25*ps.wrong)+' s of margin). Ideal: '+G.F.best.map(i=>i+1).join(', ')+'.'):L('Los tres controles, en los accesos por los que llega la gente: colas cortas.','All three checkpoints at the entrances people arrive by: short queues.'),pts:ps.pc,max:12});
  G.dec.push({ph:1,ok:ps.near.length?1:2,t:L('Entrada de la autoridad','Dignitary entrance'),r:entName(ai),why:ps.near.length?L('El coche llega a pocos metros de la cola del acceso '+ps.near.map(i=>i+1).join(', ')+': la autoridad se cruza con público sin revisar. Mejor el otro acceso para coches.','The car arrives a few metres from the queue at entrance '+ps.near.map(i=>i+1).join(', ')+': the dignitary crosses unchecked public. The other vehicle entrance was better.'):L('El coche llega por un acceso sin colas cerca: la autoridad no se cruza con el público.','The car arrives at an entrance with no queues nearby: the dignitary never crosses the public.'),pts:ps.pa,max:13});
  G.phase='chk'; G.t=0; G.pi=0;
  lg('Perímetro listo: '+G.E.filter(v=>v==='x').length+' accesos cerrados con vallas y una pareja, 3 controles y la entrada de la autoridad.','Perimeter set: '+G.E.filter(v=>v==='x').length+' entrances closed with barriers and a pair, 3 checkpoints and the dignitary entrance.','good');
  lg(' Se abren los controles. Tú mandas el '+entName(G.mine)+', el que más gente recibe.',' Checkpoints open. You lead '+entName(G.mine)+', the busiest one.','good');
  nextP(); }
function nextP(){ if(G.pi>=G.ord.length){ endChk(); return; } const p=PEOPLE[G.ord[G.pi]]; G.cur={p,n:G.pi,did:[],seen:[],err:[]}; }
function arrived(){ return Math.min(PEOPLE.length,3+Math.floor(G.t*PEOPLE.length/G.bud)); }
function waiting(){ return Math.max(0,arrived()-G.pi-1); }
function indicio(c){ const p=c.p; return (p.arco==='beep2'&&c.did.indexOf('rep')>=0)||c.did.indexOf('wand')>=0&&p.wd||p.arco==='pm'||p.vis; }
function doAct(k){ const c=G.cur, p=c.p; if(!c||G.phase!=='chk') return; const A=ACT[k]; G.t+=A[0]; c.did.push(k); let msg='', cls='';
  if(k==='arco'){ if(p.arco==='pm'){ msg=L('No debía pasar por el arco: lleva marcapasos.','He should not go through the arch: he has a pacemaker.'); cls='b'; c.err.push(L('arco con marcapasos','arch with a pacemaker')); } else if(p.arco==='ok'){ msg=L('El arco no pita.','The arch stays silent.'); cls='g'; } else { msg=L('El arco pita.','The arch beeps.'); cls='p'; } }
  else if(k==='rep'){ if(p.arco==='beep'){ msg=(p.pk?L(p.pk[0],p.pk[1])+' ':'')+L('Repite el arco: ya no pita.','Repeats the arch: clear now.'); cls='g'; } else { msg=(p.pk?L(p.pk[0],p.pk[1])+' ':'')+L('Repite el arco: sigue pitando.','Repeats the arch: still beeping.'); cls='p'; } }
  else if(k==='bolso'){ msg=L(p.bagC[0],p.bagC[1]); cls=p.bad==='bag'?'b':'g'; if(p.bad==='bag') c.seen.push('item'); }
  else if(k==='wand'){ if(p.arco==='pm'){ msg=L('El detector de mano tampoco se pasa sobre un marcapasos.','The hand-held detector should not go over a pacemaker either.'); cls='b'; c.err.push(L('detector de mano con marcapasos','hand detector with a pacemaker')); } else if(p.wd){ msg=L(p.wd[0],p.wd[1]); cls='p'; } else { msg=L('El detector de mano no marca nada.','The hand-held detector finds nothing.'); cls='g'; } }
  else if(k==='cacheo'){ if(!indicio(c)){ msg=L('Cacheo sin indicios: no había motivo (art. 20). No encuentras nada y la persona se queja con razón.','Pat-down with no grounds: there was no reason (art. 20). You find nothing and the person rightly complains.'); cls='b'; c.err.push(L('cacheo sin indicios','pat-down without grounds')); } else { msg=p.body?L(p.body[0],p.body[1]):L('Nada encima.','Nothing on the body.'); cls=p.bad==='body'?'b':'g'; if(p.bad==='body') c.seen.push('item'); } }
  else if(k==='radio'){ msg=L('Avisas por radio.','You radio it in.'); cls='g'; }
  G.fb={cls,b:L(A[1],A[2]),t:msg}; checkPress(); if(G.t>=G.bud) closeChk(); }
function canKeep(c){ return c.seen.indexOf('item')>=0||c.p.vis; }
function checkPress(){ if(!G.pressHit&&waiting()>=6){ G.pressHit=true; lg('La cola empuja las vallas de tu acceso: un compañero tiene que dejar su puesto para contenerla.','The queue pushes the barriers at your entrance: a colleague has to leave his post to hold it.','bad'); } }
function finish(k){ const c=G.cur, p=c.p; if(!c) return; let pts=0, ok=0, why=p.why?L(p.why[0],p.why[1]):'', extra='';
  if(p.leave){ const o=p.opts.find(o=>o.id===k); G.t+=k==='radio'?3:k==='go'?20:1; pts=o.ok===2?4:o.ok===1?1:0; ok=o.ok; why=L(o.why[0],o.why[1]); G.dec.push({ph:2,ok,t:L(p.d[0],p.d[1]),r:L(o.es,o.en),why,pts,max:4}); G.fb={cls:ok===2?'g':ok?'p':'b',b:(ok===2?'✓ ':ok?'~ ':'✗ ')+L(o.es,o.en),t:why}; G.pi++; G.done++; checkPress(); if(G.t>=G.bud) closeChk(); else nextP(); return; }
  G.t+=FIN[k][0]; const miss=p.need.filter(n=>c.did.indexOf(n)<0);
  const letIn=(k==='in'&&p.bad)||(k==='in'&&p.vis);
  if(k===p.fin){ if(!miss.length&&!c.err.length){ pts=4; ok=2; } else if(p.strict&&miss.length){ pts=0; ok=0; extra=L('Le dejaste pasar sin pasar por el arco.','You let him in without the arch.'); } else { pts=2; ok=1; extra=(miss.length?L('Faltó: ','Missing: ')+miss.map(n=>L(ACT[n][1],ACT[n][2]).toLowerCase()).join(', ')+'. ':'')+(c.err.length?L('Error: ','Error: ')+c.err.join(', ')+'. ':''); } }
  else if(p.alt&&p.alt[k]!=null){ pts=p.alt[k]; ok=1; extra=L('Excesivo: bastaba con retener el objeto.','Too much: keeping the object was enough.'); }
  else { pts=0; ok=0; if(letIn) extra=p.weapon?L('¡Ha entrado con una '+p.item[0]+'!','He got in with a '+p.item[1]+'!'):L('Ha entrado con: '+p.item[0]+'.','Got in with: '+p.item[1]+'.'); else if(k==='out') extra=L('Le dejas fuera sin motivo.','You turn them away for no reason.'); else if(k==='keep') extra=L('No había nada que retener.','There was nothing to keep.'); }
  if(k==='in'&&p.bad==='body'&&!c.seen.length){ G.breach=true; lg('Fallo grave: alguien ha entrado con un arma blanca.','Serious failure: someone got in with a knife.','bad'); }
  if(k!=='out') G.inside++;
  G.dec.push({ph:2,ok,t:L(p.d[0],p.d[1]),r:L(FIN[k][1],FIN[k][2])+(c.did.length?' ('+c.did.map(n=>L(ACT[n][1],ACT[n][2]).toLowerCase()).join(' → ')+')':''),why:(extra?extra+' ':'')+why,pts,max:4});
  G.fb={cls:ok===2?'g':ok?'p':'b',b:(ok===2?'✓ ':ok?'~ ':'✗ ')+L(FIN[k][1],FIN[k][2]),t:(extra?extra+' ':'')+why};
  G.pi++; G.done++; checkPress(); if(G.t>=G.bud) closeChk(); else nextP(); }
function closeChk(){ if(G.phase!=='chk') return; const left=PEOPLE.length-G.pi; G.out=left; if(left>0){ lg(' Se cierran los accesos: '+left+' persona(s) de tu cola se quedan fuera.',' Entrances close: '+left+' people in your queue are left outside.','bad'); for(let i=G.pi;i<PEOPLE.length;i++){ const p=PEOPLE[G.ord[i]]; G.dec.push({ph:2,ok:0,t:L(p.d[0],p.d[1]),r:L('Se quedó fuera','Left outside'),why:L('No dio tiempo: demasiadas comprobaciones innecesarias antes.','No time left: too many unnecessary checks before.'),pts:0,max:4}); } } endChk(); }
