function visTick(dt){ const v=G.vip; if(!v||v.st!=='walk') return !!G.pulse; const tg=v.path[v.k]; const d=Math.hypot(tg[0]-v.x,tg[1]-v.y); const sp=14*dt; if(d<=sp){ v.x=tg[0]; v.y=tg[1]; v.k++; if(v.k>=v.path.length){ v.st='dais'; G.pulse=G.pulseLater; render(); return true; } } else { v.x+=(tg[0]-v.x)/d*sp; v.y+=(tg[1]-v.y)/d*sp; } return true; }
