function newBus(seed){ const M=C.MAPS.bernabeu; G={mi:'bus',seed,M,mapKey:'bernabeu',phase:'plan',apr:G&&G.apr||false,pos:[null,null,null,null],spd:null,log:[],dec:[],bs:0,ev:0,stopAt:null,delay:0,hits:0,ten:0,force:0,fb:null,pulse:null,wait:false,fx:[]};
  G.route=routeInit(M.r); G.clock=()=>clk(19*60+15+G.bs/G.route.len*12+G.delay); return G; }
function at(sp){ return G.pos.map((p,i)=>p===sp?i:-1).filter(i=>i>=0); }
function uipAt(sp){ return at(sp).some(i=>UNITS[i].k==='uip'); }
