function busPlanOk(){ return G.pos.every(p=>p)&&G.spd; }
function busPlanScore(){ let b=uipAt('B')?10:cabAt('B')?3:0; const nc=at('C').length; let c=nc>=2&&uipAt('C')?10:nc>=1?4:0; const s=G.spd==='mod'?5:0; return {b,c,s}; }
function busStart(){ const ps=busPlanScore(); G.ps=ps;
  G.dec.push({ph:1,ok:ps.b===10?2:ps.b?1:0,t:L('Punto B (grupo de riesgo)','Point B (risk group)'),r:at('B').map(i=>L(UNITS[i].es,UNITS[i].en)).join(', ')||L('nadie','nobody'),why:ps.b===10?L('Una UIP con escudos entre el grupo y la calzada: es lo que para un objeto lanzado.','A UIP with shields between the group and the road: that is what stops a thrown object.'):ps.b?L('La Caballería no para objetos y un objeto que cae cerca asusta a los caballos: aquí hacía falta UIP con escudos.','Horses do not stop objects and an object landing nearby startles them: shields (UIP) were needed here.'):L('Nadie en el punto de riesgo conocido: la información previa está para usarla.','Nobody at the known risk point: prior intelligence is there to be used.'),pts:ps.b,max:10});
  G.dec.push({ph:1,ok:ps.c===10?2:ps.c?1:0,t:L('Punto C (llegada)','Point C (arrival)'),r:at('C').map(i=>L(UNITS[i].es,UNITS[i].en)).join(', ')||L('nadie','nobody'),why:ps.c===10?L('Dos unidades (al menos una UIP) bastan para hacer un pasillo a los dos lados hasta la puerta.','Two units (at least one UIP) are enough for a corridor on both sides up to the gate.'):L('Para el pasillo de llegada hacen falta dos unidades, una de ellas UIP: con menos solo cubres un lado.','The arrival corridor needs two units, one of them UIP: with fewer you cover only one side.'),pts:ps.c,max:10});
  G.dec.push({ph:1,ok:ps.s?2:0,t:L('Velocidad del convoy','Convoy speed'),r:L(SPEED[G.spd][0],SPEED[G.spd][1]),why:ps.s?L('Constante y moderada: da tiempo a apartarse y no deja al autobús parado entre la gente.','Steady and moderate: people have time to step back and the bus never sits still in the crowd.'):G.spd==='lento'?L('Despacio, el autobús pasa más tiempo expuesto y llega tarde.','Slowly, the bus spends longer exposed and arrives late.'):L('Rápido entre gente que se acerca a la calzada es riesgo de atropello.','Fast past people stepping into the road risks running someone over.'),pts:ps.s,max:5});
  if(G.spd==='lento') G.delay+=3;
  lg(' Sale el autobús del hotel. Motos delante y detrás; '+UNITS.map((u,i)=>L(u.es,u.en)+' en '+G.pos[i]).join(', ')+'.',' The bus leaves the hotel. Motorcycles ahead and behind; '+UNITS.map((u,i)=>L(u.es,u.en)+' at '+G.pos[i]).join(', ')+'.','good');
  G.phase='drive'; G.ev=0; G.stopAt=busEvents()[0].s; G.cam=camBox(); animOn(); }
